    n = len(var)
    rows = len(live_idx)
    A = np.zeros((rows, n))
    for j, (k, p) in enumerate(var):
        for e in paths[k][p]:
            A[live_idx.index(e) if False else _row[e], j] = 1.0 / caps[e]
    Bl = np.array([B[e] for e in live_idx], dtype=float)
    Q = np.eye(n) + float(rho) * (A.T @ A)
    q = -float(rho) * (A.T @ Bl)
    return Q, q


_row = {}


def solve_worker(owned, paths, caps, demand, mode, rho, B):
    """Return the proposal dictionary for one captured worker problem."""
    E = len(caps)
    live_idx = [e for e in range(E) if caps[e] > 0.0]
    row_of = {e: i for i, e in enumerate(live_idx)}
    avail = {k: available_slots(paths[k], caps) for k in owned}
    if mode == "route":
        unroutable = [k for k in owned if demand[k] > 0.0 and not avail[k]]
        if unroutable:
            return {"status": "infeasible", "unroutable": [int(k) for k in unroutable]}

    var = []
    for k in owned:
        if demand[k] <= 0.0:
            continue
        for p in avail[k]:
            var.append((k, p))
    n = len(var)
    pos_of = {kp: j for j, kp in enumerate(var)}

    rows = []
    for k in owned:
        if demand[k] > 0.0 and avail[k]:
            rows.append(k)
    m = len(rows)

    x = np.zeros(n)
    lam = np.zeros(m)
    if n:
        A = np.zeros((len(live_idx), n))
        for j, (k, p) in enumerate(var):
            for e in paths[k][p]:
                A[row_of[e], j] = 1.0 / caps[e]
        Bl = np.array([B[e] for e in live_idx], dtype=float)
        r = float(rho)
        Q = np.eye(n) + r * (A.T @ A)
        q = -r * (A.T @ Bl)
        if mode == "admit":
            q = q - 1.0
        C = np.zeros((m, n))
        d = np.zeros(m)
        eq = [mode == "route"] * m
        for i, k in enumerate(rows):
            for p in avail[k]:
                C[i, pos_of[(k, p)]] = 1.0
            d[i] = float(demand[k])
        starts = []
        if mode == "route":
            s = np.zeros(n)
            for i, k in enumerate(rows):
                v = d[i] / len(avail[k])
                for p in avail[k]:
                    s[pos_of[(k, p)]] = v
            starts.append(s)
            s2 = np.zeros(n)
            for i, k in enumerate(rows):
                s2[pos_of[(k, min(rows.index(k), 0))]] = 0.0
            for i, k in enumerate(rows):
                s2[pos_of[(k, avail[k][0])]] = d[i]
            starts.append(s2)
        else:
            starts.append(np.zeros(n))
            s = np.zeros(n)
            for i, k in enumerate(rows):
                v = min(d[i] / len(avail[k]), 1.0)
                for p in avail[k]:
                    s[pos_of[(k, p)]] = v
            starts.append(s)
        best = None
        for x0 in starts:
            xs, ls, ok = solve_qp(Q, q, C, d, eq, x0)
            cand = _certify(xs, var, rows, paths, caps, demand, mode, rho, B, live_idx)
            if best is None or cand[0] < best[0]:
                best = cand
            if cand[0] <= 0.0:
                break
        x = best[1]
        lam = best[2]

    # assemble flow (all original slots, exact zeros where forced)
    xval = {}
    for j, (k, p) in enumerate(var):
        xval[(k, p)] = float(x[j])
    flow = []
    for k in owned:
        row = [0.0] * len(paths[k])
        for p in range(len(paths[k])):
            v = xval.get((k, p))
            if v is not None and v > 0.0:
                row[p] = v
        flow.append(row)

    L = np.zeros(E)
    for k in owned:
        pathrow = paths[k]
        for p, v in enumerate(flow[owned.index(k)]):
            if v != 0.0:
                for e in pathrow[p]:
                    L[e] += v

    # derivative and potentials
    resid = np.zeros(E)
    for e in live_idx:
        resid[e] = L[e] / caps[e] - B[e]
    r = float(rho)
    potential = []
    for k in owned:
        if demand[k] <= 0.0:
            potential.append(0.0)
            continue
        best_g = None
        anypos = False
        for p in avail[k]:
            v = xval.get((k, p), 0.0)
            g = v
            for e in paths[k][p]:
                g += r * resid[e] / caps[e]
            if mode == "admit":
                g -= 1.0
            if v > 0.0:
                anypos = True
                if best_g is None or g > best_g:
                    best_g = g
        lam_k = -best_g if (anypos and best_g is not None) else 0.0
        if mode == "admit" and lam_k < 0.0:
            lam_k = 0.0
        potential.append(float(lam_k))

    return {
        "status": "optimal",
        "flow": flow,
        "edge_load": [float(v) for v in L],
        "potential": potential,
    }


def _certify(x, var, rows, paths, caps, demand, mode, rho, B, live_idx):
    """Return (violation, x, lam) for a candidate primal point."""
    n = len(x)
    m = len(rows)
    worst = 0.0
    E = len(caps)
    L = np.zeros(E)
    for j, (k, p) in enumerate(var):
        v = float(x[j])
        if v != 0.0:
            for e in paths[k][p]:
                L[e] += v
    resid = np.zeros(E)
    for e in live_idx:
        resid[e] = L[e] / caps[e] - B[e]
    r = float(rho)
    # per commodity sums
    sums = {}
    for j, (k, p) in enumerate(var):
        sums[k] = sums.get(k, 0.0) + float(x[j])
    for k in rows:
        s = sums.get(k, 0.0)
        if mode == "route":
            worst = max(worst, abs(s - demand[k]) / max(1.0, abs(demand[k])))
        else:
            worst = max(worst, max(0.0, s - demand[k]) / max(1.0, abs(demand[k])))
    if x.min() < 0.0:
        worst = max(worst, -x.min() / max(1.0, float(np.abs(x).max())))
    lam = np.zeros(m)
    for i, k in enumerate(rows):
        gs = []
        anypos = False
        for p in available_slots(paths[k], caps):
            j = None
            for jj, kp in enumerate(var):
                if kp == (k, p):
                    j = jj
                    break
            v = float(x[j]) if j is not None else 0.0
            g = v
            for e in paths[k][p]:
                g += r * resid[e] / caps[e]
            if mode == "admit":
                g -= 1.0
            gs.append((v, g))
            if v > 0.0:
                anypos = True
        if not anypos:
            lam[i] = 0.0
            continue
        mx = max(g for v, g in gs if v > 0.0)
        lam[i] = -mx
        if mode == "admit" and lam[i] < 0.0:
            lam[i] = 0.0
    # f and D
    f = 0.0
    for j in range(n):
        f += 0.5 * float(x[j]) ** 2
    for e in live_idx:
        f += 0.5 * r * resid[e] ** 2
    if mode == "admit":
        f -= float(x.sum())
    D = f
    for j, (k, p) in enumerate(var):
        v = float(x[j])
        if v == 0.0:
            continue
        g = v
        for e in paths[k][p]:
            g += r * resid[e] / caps[e]
        if mode == "admit":
            g -= 1.0
        D -= v * g
    for i, k in enumerate(rows):
        D -= demand[k] * lam[i]
    if abs(f - D) > tol(f, D):
        worst = max(worst, abs(f - D) / max(1.0, abs(f), abs(D)))
    # sign conditions
    for i, k in enumerate(rows):
        for p in available_slots(paths[k], caps):
            j = None
            for jj, kp in enumerate(var):
                if kp == (k, p):
                    j = jj
                    break
            v = float(x[j]) if j is not None else 0.0
            g = v
            for e in paths[k][p]:
                g += r * resid[e] / caps[e]
            if mode == "admit":
                g -= 1.0
            val = g + lam[i]
            if val < -tol(val, 0.0):
                worst = max(worst, -val / max(1.0, abs(val)))
    return worst, x, lam
